def dc_subterms(value):
    out=[]
    todo=[value]
    while todo:
        item=todo.pop()
        if isinstance(item,list) and item:
            out.append(item)
            i=1
            while i<len(item):
                if isinstance(item[i],list):
                    todo.append(item[i])
                i+=1
    return out

def dc_has(value,name):
    for item in dc_subterms(value):
        if item[0]==name:
            return True
    return False

def dc_unique(values):
    out=[]
    for value in values:
        if value not in out:
            out.append(value)
    return out

def dc_entries(premises):
    nodes=premises.get('nodes',[])
    roots=premises.get('roots',[])
    byid={}
    for node in nodes:
        if isinstance(node,dict):
            byid[node.get('id')]=node
    out=[]
    for root in roots:
        todo=[root]
        seen=set()
        while todo:
            nid=todo.pop()
            if nid in seen or nid not in byid:
                continue
            seen.add(nid)
            node=byid[nid]
            for term in dc_subterms(node.get('term')):
                out.append((term,root))
            for child in node.get('child_ids',[]):
                todo.append(child)
    return out

def dc_old_role_tags(value,definitions):
    tags=set()
    todo=[value]
    expanded=set()
    while todo:
        item=todo.pop()
        if not isinstance(item,list) or not item:
            continue
        name=item[0]
        if name=='representatives_of' and len(item)>1:
            key=str(item[1])
            if key not in expanded:
                expanded.add(key)
                for owner,members in definitions:
                    if str(owner)==key or (isinstance(owner,list) and owner and owner[0]=='party'):
                        todo.append(members)
            continue
        if name in ('employees_of','internal_personnel_of'):
            tags.add('employees')
        elif name=='independent_contractors_of':
            tags.add('contractors')
        elif name=='consultants_of':
            tags.add('consultants')
        elif name=='agents_of':
            tags.add('agents')
        elif name in ('professional_advisors_of','legal_advisors_of','financial_advisors_of','accountants_of','lenders_of'):
            tags.add('professionals')
        elif name=='third_parties':
            tags.add('third_parties')
        i=1
        while i<len(item):
            if isinstance(item[i],list):
                todo.append(item[i])
            i+=1
    return tags

def dc_profile_has_employee(profile):
    return profile in ('recipient_employees','recipient_employees_and_contractors','recipient_employees_and_professionals','representatives_with_employees_and_professionals')

def dc_profile_has_professional(profile):
    return profile in ('recipient_employees_and_contractors','recipient_employees_and_professionals','controlled_company_employees_and_professionals','representatives_with_employees_and_professionals','professionals_without_recipient_employees')

def dc_disclosure(task,entries):
    definitions=[]
    definition_roots=[]
    absence=[]
    relevant=[]
    permissions=[]
    prohibitions=[]
    for term,root in entries:
        if term[0]=='define_representative' and len(term)==3:
            definitions.append((term[1],term[2]))
            definition_roots.append(root)
        elif term[0]=='complete_source_no_disclosure_permission':
            absence.append(root)
        elif term[0]=='bound_disclosure_permission' and len(term)==5:
            relevant.append(root)
            permissions.append((root,term[2],None))
    for term,root in entries:
        if term[0] not in ('permission','prohibition') or len(term)<3:
            continue
        action=term[2]
        if not isinstance(action,list) or len(action)!=3 or action[0]!='disclose' or not dc_has(action[1],'confidential_information'):
            continue
        relevant.append(root)
        tags=dc_old_role_tags(action[2],definitions)
        if term[0]=='permission':
            permissions.append((root,None,tags))
        else:
            prohibitions.append((root,action[2],tags))
    for root,profile,tags in permissions:
        if task=='nda-5':
            if profile is not None and dc_profile_has_employee(profile):
                return {'handled':True,'answer':'Entailment','used_nodes':[root]}
            if tags is not None and 'employees' in tags:
                return {'handled':True,'answer':'Entailment','used_nodes':[root]}
        else:
            if profile is not None and dc_profile_has_professional(profile):
                return {'handled':True,'answer':'Entailment','used_nodes':[root]}
            if tags is not None and tags.intersection({'contractors','consultants','agents','professionals','third_parties'}):
                return {'handled':True,'answer':'Entailment','used_nodes':[root]}
    for root,recipient,tags in prohibitions:
        if dc_has(recipient,'outsiders_to'):
            continue
        if task=='nda-5' and 'employees' in tags:
            return {'handled':True,'answer':'Contradiction','used_nodes':[root]}
        if task=='nda-7' and tags.intersection({'contractors','consultants','agents','professionals','third_parties'}):
            return {'handled':True,'answer':'Contradiction','used_nodes':[root]}
    if relevant or absence:
        return {'handled':True,'answer':'NotMentioned','used_nodes':dc_unique(relevant+definition_roots+absence)}
    return {'handled':False,'answer':None,'used_nodes':[]}

def dc_bound_endpoint(profile):
    return profile in ('return_or_destroy_on_agreement_end_or_request_all_materials','return_on_agreement_end_all_materials','return_on_relationship_end_all_materials','return_on_service_end_all_materials','return_on_request_or_destroy_on_project_end_all_materials','return_on_request_or_destroy_on_project_end_with_backup_exception','return_on_request_or_destroy_on_project_end_with_backup_and_record_copy')

def dc_bound_retention_permission(profile):
    return profile in ('return_on_request_or_destroy_on_project_end_with_backup_exception','return_on_request_or_destroy_on_project_end_with_backup_and_record_copy')

def apply(inputs,premises):
    task=inputs.get('task_id')
    if task not in ('nda-5','nda-7','nda-16','nda-20'):
        return {'handled':False,'answer':None,'used_nodes':[]}
    entries=dc_entries(premises)
    if task in ('nda-5','nda-7'):
        return dc_disclosure(task,entries)
    bound=[]
    old_disposal=[]
    retention_permissions=[]
    retention_prohibitions=[]
    absence=[]
    for term,root in entries:
        if term[0]=='bound_disposal_obligation' and len(term)==3:
            bound.append((term[2],root))
        elif term[0]=='disposal_obligation' and len(term)==5:
            old_disposal.append((term,root))
        elif term[0] in ('retention_permission','retention_exception'):
            retention_permissions.append(root)
        elif term[0] in ('retention_prohibition','absolute_retention_prohibition'):
            retention_prohibitions.append(root)
        elif term[0]=='complete_source_no_disposal_obligation':
            absence.append(root)
    if task=='nda-16':
        endpoints=[]
        relevant=[]
        for profile,root in bound:
            relevant.append(root)
            if dc_bound_endpoint(profile):
                endpoints.append(root)
        for term,root in old_disposal:
            if dc_has(term[2],'return_to') or dc_has(term[2],'destroy'):
                relevant.append(root)
                if dc_has(term[3],'agreement_termination') or dc_has(term[3],'service_termination') or dc_has(term[3],'relationship_termination') or dc_has(term[3],'relationship_nonformation_deadline') or dc_has(term[3],'purpose_completion'):
                    endpoints.append(root)
        if endpoints:
            return {'handled':True,'answer':'Entailment','used_nodes':dc_unique(endpoints)}
        if relevant or absence:
            return {'handled':True,'answer':'NotMentioned','used_nodes':dc_unique(relevant+absence)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if retention_permissions:
        return {'handled':True,'answer':'Entailment','used_nodes':dc_unique(retention_permissions)}
    bound_permissions=[]
    bound_all=[]
    for profile,root in bound:
        bound_all.append(root)
        if dc_bound_retention_permission(profile):
            bound_permissions.append(root)
    if bound_permissions:
        return {'handled':True,'answer':'Entailment','used_nodes':dc_unique(bound_permissions)}
    if retention_prohibitions:
        return {'handled':True,'answer':'Contradiction','used_nodes':dc_unique(retention_prohibitions)}
    if bound_all:
        return {'handled':True,'answer':'Contradiction','used_nodes':dc_unique(bound_all)}
    old_relevant=[]
    for term,root in old_disposal:
        if dc_has(term[2],'return_to') or dc_has(term[2],'destroy'):
            old_relevant.append(root)
    if old_relevant or absence:
        return {'handled':True,'answer':'NotMentioned','used_nodes':dc_unique(old_relevant+absence)}
    return {'handled':False,'answer':None,'used_nodes':[]}

