def planner_rows(value):
    if isinstance(value,list):
        return value
    if isinstance(value,dict):
        rows=value.get('answers')
        if isinstance(rows,list):
            return rows
        if isinstance(rows,dict):
            return list(rows.values())
        return list(value.values())
    return []

def planner_answer(rows,qid):
    for row in rows:
        if isinstance(row,dict) and row.get('id')==qid:
            return row
    return None

def planner_evidence_ids(answer):
    out=[]
    if not isinstance(answer,dict):
        return out
    evidence=answer.get('evidence',[])
    if isinstance(evidence,dict):
        evidence=[evidence]
    for item in evidence:
        if isinstance(item,dict):
            uid=item.get('unit_id')
            if uid not in out:
                out.append(uid)
    return out

def planner_before_window(spans,index_value,width):
    start=max(0,index_value-width)
    out=[]
    i=start
    while i<=index_value:
        out.append(spans[i].get('id'))
        i+=1
    return out

def planner_around_window(spans,index_value,before_count,after_count):
    start=max(0,index_value-before_count)
    stop=min(len(spans)-1,index_value+after_count)
    out=[]
    i=start
    while i<=stop:
        out.append(spans[i].get('id'))
        i+=1
    return out

def planner_add(queries,answered,qid,operation,unit_ids):
    if qid in answered or not unit_ids:
        return
    queries.append({'id':qid,'operation':operation,'unit_ids':unit_ids})

def apply(inputs,premises):
    spans=[]
    for span in inputs.get('source_spans',[]):
        if isinstance(span,dict):
            spans.append(span)
    rows=planner_rows(inputs.get('semantic_answers',[]))
    answered=set()
    for row in rows:
        if isinstance(row,dict) and isinstance(row.get('id'),str):
            answered.add(row.get('id'))
    units=[]
    positions={}
    i=0
    while i<len(spans):
        uid=spans[i].get('id')
        units.append(uid)
        positions[uid]=i
        i+=1
    queries=[]
    disclosure_scout='positive_disclosure_scout_v5'
    disposal_scout='positive_disposal_scout_v5'
    planner_add(queries,answered,disclosure_scout,'operative_disclosure_positive_scout_v5',units)
    planner_add(queries,answered,disposal_scout,'operative_disposal_positive_scout_v5',units)
    disclosure_answer=planner_answer(rows,disclosure_scout)
    if isinstance(disclosure_answer,dict) and disclosure_answer.get('choice')=='candidate_found':
        for uid in planner_evidence_ids(disclosure_answer):
            if uid in positions:
                window=planner_before_window(spans,positions[uid],4)
                planner_add(queries,answered,'disclosure_effect_'+str(uid),'disclosure_permission_effect_form_v1',window)
                planner_add(queries,answered,'disclosure_roles_'+str(uid),'disclosure_recipient_profile_v1',window)
                planner_add(queries,answered,'disclosure_conditions_'+str(uid),'disclosure_condition_profile_v1',window)
    disposal_answer=planner_answer(rows,disposal_scout)
    if isinstance(disposal_answer,dict) and disposal_answer.get('choice')=='candidate_found':
        for uid in planner_evidence_ids(disposal_answer):
            if uid in positions:
                window=planner_around_window(spans,positions[uid],3,2)
                planner_add(queries,answered,'disposal_binding_'+str(uid),'disposal_norm_binding_v1',window)
    return {'queries':queries}
